      // window.open(this.telgramurl)
    },
    getMons(mons) {
      throughtling({ actcode: 'actThroughtHX', mons: mons }).then((res) => {
        this.$toast(res.msg)
        this.initActinfo()
      })
    },
    initActinfo() {
      getActinfo({ actcode: 'actThroughtHX' }).then(res => {
        this.taskList = res.datalist
